const raw = input.contract_text || '';
const cleaned = raw.replace(/\s+/g, ' ').trim();
if (cleaned.length < 80) {
  return { valid: false, cleaned_text: '', error: 'Contract text is empty or too short to review. Please provide the full contract text.' };
}
const markers = ['agreement', 'party', 'parties', 'term', 'liability', 'termination', 'hereby', 'shall', 'clause', 'section', 'contract', 'renew', 'notice', 'governing'];
const lower = cleaned.toLowerCase();
const hits = markers.filter(m => lower.includes(m)).length;
if (hits < 2) {
  return { valid: false, cleaned_text: '', error: 'The provided text does not appear to be a contract. Please supply contract document text.' };
}
return { valid: true, cleaned_text: cleaned, error: null };

const norm = s => (s || '').toLowerCase().replace(/\s+/g, ' ').trim();
const text = norm(nodes.validate_contract.output.cleaned_text);
const cats = ['auto_renewal', 'unlimited_liability', 'unilateral_changes', 'data_sharing', 'non_compete'];
const all = nodes.extract_findings.output.findings || [];
const findings = all.filter(f => cats.includes(f.category) && f.quote && text.includes(norm(f.quote)));
const coverage_summary = {};
for (const c of cats) {
  const n = findings.filter(f => f.category === c).length;
  coverage_summary[c] = n > 0 ? 'detected (' + n + ' finding' + (n > 1 ? 's' : '') + ')' : 'not detected';
}
return { findings, coverage_summary };

