const approved = !!(input.approval_decision && input.approval_decision.approve);
const findings = nodes.merge_revisions.output.risk_findings ?? nodes.build_coverage.output.findings ?? [];
const coverage = nodes.merge_revisions.output.coverage_summary ?? nodes.build_coverage.output.coverage_summary ?? null;
if (!approved) {
  return { risk_findings: findings, review_status: 'pending_approval', approval_record: null, coverage_summary: coverage, error: null };
}
return {
  risk_findings: findings,
  review_status: 'final',
  approval_record: {
    reviewer: (input.approval_decision && input.approval_decision.reviewer) || 'human reviewer',
    timestamp: new Date().toISOString(),
    comments: (input.approval_decision && input.approval_decision.comments) || ''
  },
  coverage_summary: coverage,
  error: null
};
